46	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
47	        assertEquals(ErrorCode.INVALID_REQUEST,
48	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
49	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
50	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
